/* ─────────────────────────────────────────────────────────────────────────── */
/* occupancy — what `spawns`, `ai` and the minimap ask about the map            */
/* ─────────────────────────────────────────────────────────────────────────── */

/** A `[x, z, ry, len]` wall row as an axis-aligned `[x0, z0, x1, z1]` rect. */
function wallRect(x, z, ry, len, t) {
  const hx = (ry === 0 ? len : t) / 2;
  const hz = (ry === 0 ? t : len) / 2;
  return [x - hx, z - hz, x + hx, z + hz];
}

/** Solid footprints as `[x0, z0, x1, z1]`, built once from the tables above. */
const BLOCKERS = (() => {
  const out = [];
  for (const h of HOUSES) out.push([h.x - h.w / 2, h.z - h.d / 2, h.x + h.w / 2, h.z + h.d / 2]);
  for (const [x, z, w, d] of SHEDS) out.push([x - w / 2, z - d / 2, x + w / 2, z + d / 2]);
  for (const [x, z, ry, len] of YARD_WALLS) out.push(wallRect(x, z, ry, len, 0.35));
  for (const [x, z, ry, len] of STREET_BLOCKS) out.push(wallRect(x, z, ry, len, 0.8));
  for (const [x, z, ry, len] of MOUTH_BLOCKS) out.push(wallRect(x, z, ry, len, 0.9));
  // The sign's two poles, so nothing gets dressed or spawned inside them.
  for (const sx of [-1, 1]) out.push([sx * SIGN.poleX - 0.3, SIGN.z - 0.3, sx * SIGN.poleX + 0.3, SIGN.z + 0.3]);
  return out;
})();

/** True inside (or within `m` of) anything solid standing on the compound floor. */
export function inSolid(x, z, m = 0.3) {
  for (let i = 0; i < BLOCKERS.length; i++) {
    const b = BLOCKERS[i];
    if (x > b[0] - m && x < b[2] + m && z > b[1] - m && z < b[3] + m) return true;
  }
  return false;
}

/**
 * Can a character stand here, in LEVEL space? Inside the wall and off every
 * footprint. Only ever a first filter — real collision decides, in
 * `buildSpawnPoints`.
 */
export function standableAtNuketown(x, z, margin = 0.55) {
  if (Math.abs(x) > NUKE.halfX - 0.8 - margin) return false;
  if (Math.abs(z) > NUKE.halfZ - 0.8 - margin) return false;
  return !inSolid(x, z, margin);
}

/** True where a character can stand outdoors — what the minimap draws as floor. */
export function isOpenNuketown(x, z, m = 0.3) {
  if (Math.abs(x) > NUKE.halfX - 0.6) return false;
  if (Math.abs(z) > NUKE.halfZ - 0.6) return false;
  return !inSolid(x, z, m);
}

/**
 * Analytic floor height. The compound is a poured apron, so this is dead flat
 * inside the wall; outside it the desert rolls away and climbs into a ridge.
 *
 * The ridge is not scenery for its own sake. From an upstairs window the camera
 * clears a 3.2 m wall, and without it the whole horizon is the terrain plane
 * meeting the sky in one straight pale band — the flat cut-out read the quality
 * bar exists to prevent. Doing it in the height field costs nothing: the terrain
 * mesh already samples this, so the ridge is free and its collision comes with it.
 *
 * Physics owns the exact answer — this is the hint props are dropped on.
 */
export function groundYNuketown(x, z) {
  const out = Math.max(Math.abs(x) - NUKE.halfX, Math.abs(z) - NUKE.halfZ);
  if (out <= 0) return 0.02;
  const t = Math.min(1, out / 12);
  const roll = (fbm3(x * 0.05, 7.3, z * 0.05, 3) - 0.5) * 1.2 * t;
  // Starts 9 m beyond the wall and takes 26 m to reach full height, so the near
  // desert still reads as flat ground and the climb is all in the distance.
  const ridge = Math.min(1, Math.max(0, (out - 9) / 26));
  return 0.02 + roll + ridge * ridge * (4.0 + fbm3(x * 0.02, 2.7, z * 0.02, 2) * 8.0);
}

/* ─────────────────────────────────────────────────────────────────────────── */
/* geometry helpers                                                            */
/* ─────────────────────────────────────────────────────────────────────────── */

const _wp = [0, 0];

/** Point `u` metres along a wall centred at (cx, cz) and rotated by `ry`. */
function alongWall(cx, cz, ry, u, out) {
  out[0] = cx + Math.cos(ry) * u;
  out[1] = cz - Math.sin(ry) * u;
  return out;
}

/** Add a box in panel space AND its collision proxy, converting once. */
function pbox(A, pm, key, x, y, z, ry, sx, sy, sz, masks) {
  A.add(key, BOX(A), LL(pm, x, y, z, ry, sx, sy, sz), { masks: masks ?? [0.55, 0.45, 0.25] });
  const w = worldOf(pm, x, y, z);
  A.box(A.surfaceOf(key), w[0], w[1], w[2], sx, sy, sz, ry + ryOf(pm));
}

/**
 * One storey of wall with real openings punched through it.
 *
 * `holes` are `[{ u, w, y, h }]` in wall-local coordinates: `u` along the wall
 * from its centre, `y` up from `y0`. The wall is emitted as the solid spans
 * BETWEEN the holes plus a lintel over and a sill under each, so a doorway is a
 * genuine hole in the collision hull rather than a thin panel the player has to
 * be teleported through.
 */
function wallWithHoles(A, pm, key, cx, cz, ry, len, y0, h, t, holes = [], masks) {
  const seg = (u, w, yc, hh) => {
    if (w < 0.02 || hh < 0.02) return;
    alongWall(cx, cz, ry, u, _wp);
    pbox(A, pm, key, _wp[0], yc, _wp[1], ry, w, hh, t, masks);
  };
  const sorted = [...holes].sort((a, b) => a.u - b.u);
  let cursor = -len / 2;
  for (const o of sorted) {
    const x0 = o.u - o.w / 2;
    const x1 = o.u + o.w / 2;
    if (x0 > cursor) seg((cursor + x0) / 2, x0 - cursor, y0 + h / 2, h);
    const oy = o.y ?? 0;
    const oh = o.h ?? h;
    if (oy > 0.02) seg(o.u, o.w, y0 + oy / 2, oy); // sill
    if (oy + oh < h - 0.02) seg(o.u, o.w, y0 + (oy + oh + h) / 2, h - oy - oh); // lintel
    cursor = Math.max(cursor, x1);
  }
  if (cursor < len / 2) seg((cursor + len / 2) / 2, len / 2 - cursor, y0 + h / 2, h);
}

/** A low freestanding wall from a `[x, z, ry, len]` row, with its proxy. */
function lowWall(A, key, x, z, ry, len, h, t, masks) {
  A.add(key, BOX(A), LL(IDENT, x, h / 2, z, ry, len, h, t), { masks: masks ?? [0.6, 0.5, 0.3] });
  A.box(A.surfaceOf(key), x, h / 2, z, len, h, t, ry);
  // A capping course, so the top edge catches light instead of reading as a cut.
  A.add(key, BOX(A), LL(IDENT, x, h + 0.05, z, ry, len + 0.12, 0.1, t + 0.12), { masks: [0.85, 0.3, 0.15] });
}

/* ─────────────────────────────────────────────────────────────────────────── */
/* the build                                                                   */
/* ─────────────────────────────────────────────────────────────────────────── */

function buildGround(A, rng) {
  const richSurfaces = A.quality !== 'performance';
  // ------------------------------------------------------------- desert --
  const S = 190;
  const N = 46;
  const terrain = new THREE.PlaneGeometry(S, S, N, N);
  terrain.rotateX(-Math.PI / 2);
  const pa = terrain.getAttribute('position');
  for (let i = 0; i < pa.count; i++) {
    pa.setY(i, groundYNuketown(pa.getX(i), pa.getZ(i)) - 0.04);
  }
  terrain.computeVertexNormals();
  paintMasks(terrain, (x, y, z, nx, ny, nz, out) => {
    out[1] = 0.2 + fbm3(x * 0.28, 2.1, z * 0.28, 2) * 0.4;
    out[0] = 0.18;
  });
  A.add(richSurfaces ? 'dirt' : 'gb_grey', terrain, null);
  A.collideGeo('sand', terrain);
  terrain.dispose();

  // ------------------------------------------------------------- apron --
  // One subdivided plane so grazing light finds something, and one flat
  // collision box under it so the controller never feels the triangles.
  const W = NUKE.halfX * 2;
  const D = NUKE.halfZ * 2;
  const apron = new THREE.PlaneGeometry(W, D, 26, 22);
  apron.rotateX(-Math.PI / 2);
  const aa = apron.getAttribute('position');
  for (let i = 0; i < aa.count; i++) {
    const x = aa.getX(i);
    const z = aa.getZ(i);
    aa.setY(i, 0.03 + (fbm3(x * 0.4 + 5, 3.3, z * 0.4, 3) - 0.5) * 0.05);
  }
  apron.computeVertexNormals();
  paintMasks(apron, (x, y, z, nx, ny, nz, out) => {
    const n = fbm3(x * 0.6, 4.9, z * 0.6, 3);
    out[0] = 0.2 + n * 0.26;
    out[1] = 0.12 + n * 0.2;
  });
  A.add(richSurfaces ? 'floor_concrete' : 'gb_grid', apron, null);
  A.box('dirt', 0, -0.25, 0, W, 0.5, D);
  apron.dispose();

  // ------------------------------------------------------------ street --
  // The asphalt is a separate flat sheet laid 1 cm over the apron rather than a
  // hole cut in it: two overlapping planes cost one extra draw call, and cutting
  // the apron would put a seam exactly where players spend the whole match.
  const street = new THREE.PlaneGeometry(NUKE.streetHalf * 2, D, 6, 22);
  street.rotateX(-Math.PI / 2);
  const sa = street.getAttribute('position');
  for (let i = 0; i < sa.count; i++) {
    const x = sa.getX(i);
    const z = sa.getZ(i);
    // A shallow camber to the crown, the way a road actually sheds water.
    sa.setY(i, 0.05 + Math.cos((x / NUKE.streetHalf) * H) * 0.035 + (fbm3(x * 0.5, 8.2, z * 0.5, 2) - 0.5) * 0.02);
  }
  street.computeVertexNormals();
  paintMasks(street, (x, y, z, nx, ny, nz, out) => {
    out[0] = 0.15;
    out[1] = 0.25 + Math.abs(x / NUKE.streetHalf) * 0.35;
  });
  A.add(richSurfaces ? 'gb_asphalt' : 'gb_grid', street, null);

  // Broken centre line + short edge markers. They merge into the house plaster
  // batch, so this adds geometry but no new material draw call.
  for (let z = -17; z <= 17; z += 6) {
    A.add(
      richSurfaces ? 'gb_marking' : 'gb_white',
      BOX_THIN(A),
      LL(IDENT, 0, 0.095, z, 0, 0.12, 0.012, 2.35),
      { masks: [0.2, 0.18, 0.08] }
    );
  }
  for (const sx of [-1, 1])
    A.add(
      richSurfaces ? 'gb_marking' : 'gb_white',
      BOX_THIN(A),
      LL(IDENT, sx * (NUKE.streetHalf - 0.35), 0.088, 0, 0, 0.09, 0.01, D - 2.5),
      { masks: [0.25, 0.2, 0.1] }
    );

  street.dispose();

  // Kerbs: a 0.14 m step each side. Low enough to walk over, which is what the
  // controller's mantle is for, and the one line that makes a road read as a road.
  for (const sx of [-1, 1]) {
    A.add('gb_grid', BOX(A), LL(IDENT, sx * (NUKE.streetHalf + 0.7), 0.07, 0, 0, 1.4, 0.14, D), {
      masks: [0.7, 0.4, 0.2],
    });
  }

  if (richSurfaces) {
    // Sparse safety-yellow curb tabs: strong refinery cue, no extra material
    // family because they merge into the existing gb_accent batch.
    for (const sx of [-1, 1])
      for (let z = -16.5; z <= 16.5; z += 5.5)
        A.add(
          'gb_accent',
          BOX_THIN(A),
          LL(IDENT, sx * (NUKE.streetHalf + 0.68), 0.148, z, 0, 1.15, 0.025, 0.62),
          null
        );
  }

  if (richSurfaces) {
    // Sparse low-poly palms, matching the clean low-graphics reference style:
    // one trunk batch + one opaque leaf batch, no alpha cards, no wind shader.
    const trunk = A.cache('nuke:palm-trunk', () => {
      const g = new THREE.CylinderGeometry(0.58, 0.82, 1, 7, 1, false);
      g.computeVertexNormals();
      return g;
    });
    const leaf = BOX_THIN(A);
    for (const [px, pz, ps, base] of [
      [-24.0, -15.5, 1.0, 0.2],
      [23.5, 15.0, 1.05, 1.1],
      [-22.8, 14.5, 0.88, 2.3],
      [22.5, -14.0, 0.92, -0.7],
    ]) {
      const th = 3.15 * ps;
      A.add('gb_dark', trunk, LL(IDENT, px, th / 2, pz, 0, 0.34 * ps, th, 0.34 * ps), {
        masks: [0.45, 0.34, 0.22],
      });
      for (let i = 0; i < 7; i++) {
        const a = base + (i / 7) * Math.PI * 2;
        const len = (1.65 + (i % 3) * 0.18) * ps;
        const cx = px + Math.cos(a) * len * 0.45;
        const cz = pz - Math.sin(a) * len * 0.45;
        A.add(
          'leaf_core',
          leaf,
          LL(IDENT, cx, th + 0.10 - (i % 2) * 0.10, cz, a, len, 0.055, 0.38 * ps, -0.22, 0),
          { masks: [0.28, 0.34, 0.18] }
        );
      }
      // Directional baked shadow: three thin frond bands plus a trunk contact
      // patch, all merged into one material batch for the entire map.
      const shA = -0.78;
      for (let j = -1; j <= 1; j++) {
        const a = shA + j * 0.22;
        const len = (2.4 - Math.abs(j) * 0.25) * ps;
        A.add(
          'gb_shadow',
          leaf,
          LL(
            IDENT,
            px + Math.cos(a) * len * 0.52,
            0.086,
            pz - Math.sin(a) * len * 0.52,
            a,
            len,
            0.012,
            0.24 * ps
          ),
          null
        );
      }
      A.add('gb_shadow', leaf, LL(IDENT, px + 0.16, 0.087, pz + 0.13, -0.78, 0.72 * ps, 0.012, 0.24 * ps), null);
    }
  }
}

/**
 * The compound wall, with the street left open at both ends.
 *
 * Each side is emitted as spans BETWEEN its openings, so the opening is a real
 * hole rather than a thin panel — the same reason `wallWithHoles` exists. The
 * openings are then parked shut by `MOUTH_BLOCKS`, which the self-test probes.
 */
function buildPerimeter(A, rng) {
  const { halfX, halfZ, wallH, wallT, streetHalf } = NUKE;
  const key = 'gb_grey';
  const masks = [0.5, 0.55, 0.35];

  // East and west runs: unbroken, full depth.
  for (const sx of [-1, 1]) {
    A.add(key, BOX(A), LL(IDENT, sx * halfX, wallH / 2, 0, 0, wallT, wallH, halfZ * 2 + wallT), { masks });
    A.box('concrete', sx * halfX, wallH / 2, 0, wallT, wallH, halfZ * 2 + wallT);
  }
  // North and south runs: two spans each, with the street mouth between them.
  for (const sz of [-1, 1]) {
    const span = halfX - streetHalf;
    for (const sx of [-1, 1]) {
      const cx = sx * (streetHalf + span / 2);
      A.add(key, BOX(A), LL(IDENT, cx, wallH / 2, sz * halfZ, 0, span, wallH, wallT), { masks });
      A.box('concrete', cx, wallH / 2, sz * halfZ, span, wallH, wallT);
    }
  }
  // A capping course all round, so the wall top is a line and not a cut edge.
  for (const sx of [-1, 1])
    A.add(key, BOX(A), LL(IDENT, sx * halfX, wallH + 0.08, 0, 0, wallT + 0.18, 0.16, halfZ * 2 + wallT), {
      masks: [0.9, 0.3, 0.1],
    });
  for (const sz of [-1, 1]) {
    const span = halfX - streetHalf;
    for (const sx of [-1, 1])
      A.add(key, BOX(A), LL(IDENT, sx * (streetHalf + span / 2), wallH + 0.08, sz * halfZ, 0, span, 0.16, wallT + 0.18), {
        masks: [0.9, 0.3, 0.1],
      });
  }

  // Piers on the mouth jambs — an opening needs an edge or it reads as damage.
  for (const sz of [-1, 1])
    for (const sx of [-1, 1]) {
      A.add(key, BOX(A), LL(IDENT, sx * streetHalf, wallH * 0.6, sz * halfZ, 0, 0.7, wallH * 1.2, 0.7), {
        masks: [0.6, 0.5, 0.3],
      });
      A.box('concrete', sx * streetHalf, wallH * 0.6, sz * halfZ, 0.7, wallH * 1.2, 0.7);
    }

  // The barrier line across each mouth.
  for (const [x, z, ry, len] of MOUTH_BLOCKS) lowWall(A, 'gb_grid', x, z, ry, len, 1.25, 0.9, [0.6, 0.6, 0.4]);

  // Background masses past the wall. `A.box` is skipped: they are outside the
  // sealed perimeter, so nothing can ever reach them and a proxy would only be
  // BVH the physics has to walk.
  for (const [x, z, w, d, h] of BACKDROP) {
    const gy = groundYNuketown(x, z);
    A.add('gb_grey', BOX(A), LL(IDENT, x, gy + h / 2, z, 0.3, w, h, d), { masks: [0.4, 0.6, 0.5] });
  }
}

/**
 * One house, built in LOCAL coordinates where +X is toward the street and the
 * house is centred on the origin. The caller supplies the panel matrix that
 * puts it on the map, so the east house is the west one with a half-turn.
 */
function decorateOpenings(A, rng, pm, cx, cz, ry, y0, holes, wallT, floor) {
  if (!holes?.length) return;
  const panel = new THREE.Matrix4().copy(LL(pm, cx, y0, cz, ry));
  const box = BOX_THIN(A);
  const frame = 'gb_dark';
  const trim = 'gb_grey';

  for (const o of holes) {
    const oy = o.y ?? 0;
    const h = o.h;
    const w = o.w;
    const x = o.u;
    const y = oy + h / 2;
    const isDoor = oy <= 0.01 && h >= 1.95;
    const fw = isDoor ? 0.085 : 0.055;
    const depth = wallT * 0.18;

    // Jambs + head. They sit in the real hole, so the facade stops reading as
    // a boolean cutout while remaining fully shoot-/walk-through.
    A.add(frame, box, LL(panel, x - w / 2 + fw / 2, y, depth, 0, fw, h, 0.075), {
      masks: [0.75, 0.4, 0.18],
    });
    A.add(frame, box, LL(panel, x + w / 2 - fw / 2, y, depth, 0, fw, h, 0.075), {
      masks: [0.75, 0.4, 0.18],
    });
    A.add(frame, box, LL(panel, x, y + h / 2 - fw / 2, depth, 0, w, fw, 0.075), {
      masks: [0.75, 0.4, 0.18],
    });

    if (isDoor) {
      // Stone threshold, still no blocking door leaf.
      A.add(trim, box, LL(panel, x, 0.045, wallT * 0.16, 0, w + 0.12, 0.09, wallT * 0.7), {
        masks: [0.55, 0.58, 0.34],
      });
      continue;
    }

    // Window bottom rail, mullion and one offset transom. These five pieces are
    // the cheapest geometry that reads as a real casement at 5-30 m.
    A.add(frame, box, LL(panel, x, y - h / 2 + fw / 2, depth, 0, w, fw, 0.075), null);
    A.add(frame, box, LL(panel, x, y, depth, 0, 0.042, h - 0.09, 0.066), null);
    A.add(frame, box, LL(panel, x, y + h * 0.16, depth, 0, w - 0.10, 0.038, 0.066), null);

    // Dark inner reveals: low-graphics games get much of their depth from
    // value separation, not expensive AO. These four strips sit inside the wall
    // thickness and make the opening read as a real recessed window instead of
    // a bright hole cut through a flat box.
    const rz = wallT * 0.34;
    A.add(frame, box, LL(panel, x - w / 2 + 0.035, y, rz, 0, 0.035, h - 0.08, wallT * 0.48), null);
    A.add(frame, box, LL(panel, x + w / 2 - 0.035, y, rz, 0, 0.035, h - 0.08, wallT * 0.48), null);
    A.add(frame, box, LL(panel, x, y - h / 2 + 0.035, rz, 0, w - 0.08, 0.035, wallT * 0.48), null);
    A.add(frame, box, LL(panel, x, y + h / 2 - 0.035, rz, 0, w - 0.08, 0.035, wallT * 0.48), null);

    // Protruding sill + lintel catch real light and create the missing facade
    // depth without another material or glass pass.
    A.add(trim, box, LL(panel, x, y - h / 2 - 0.045, -0.035, 0, w + 0.20, 0.09, wallT * 0.5), {
      masks: [0.48, 0.42, 0.26],
    });
    A.add(trim, box, LL(panel, x, y + h / 2 + 0.045, 0.01, 0, w + 0.16, 0.09, wallT * 0.4), {
      masks: [0.45, 0.46, 0.26],
    });
  }
}

function buildHouse(A, rng, spec) {
  /**
   * The panel matrix must be its OWN Matrix4, never the one `LL` hands back.
   * `LL` returns a shared module-level scratch (`kit.js`), so holding its result
   * as `pm` makes every later `LL(pm, …)` compound the house transform into
   * itself — the walls end up 10^13 m from the origin, the map still builds,
   * every self-test still passes, and the houses are simply not on screen.
   */
  const pm = new THREE.Matrix4().makeRotationY(spec.face > 0 ? 0 : Math.PI);
  pm.setPosition(spec.x, 0, spec.z);
  const hw = spec.w / 2;
  const hd = spec.d / 2;
  const { floorH, eaves, ridge } = NUKE;
  const t = 0.32;
  const key = spec.key;

  // ---- slab and first floor ---------------------------------------------
  pbox(A, pm, 'gb_grid', 0, -0.06, 0, 0, spec.w + 0.5, 0.24, spec.d + 0.5, [0.5, 0.55, 0.35]);

  // The upper floor, minus a stairwell void at the back-north corner. A stair
  // can only land on a platform at its EDGE — a flight rising inside a solid
  // slab would come up through it.
  const voidX = -hw + 2.4; // void spans x < voidX
  const voidZ = -hd + 5.2; // void spans z < voidZ
  pbox(A, pm, 'gb_white', (voidX + hw) / 2, floorH - 0.1, 0, 0, hw - voidX, 0.2, spec.d, [0.5, 0.5, 0.3]);
  pbox(A, pm, 'gb_white', (-hw + voidX) / 2, floorH - 0.1, (voidZ + hd) / 2, 0, voidX + hw, 0.2, hd - voidZ, [0.5, 0.5, 0.3]);

  // ---- the four walls ----------------------------------------------------
  const masks = [0.45, 0.5, 0.3];
  const doorH = 2.2;
  const winY = 1.0;
  const winH = 1.4;

  for (const floor of [0, 1]) {
    const y0 = floor * floorH;
    const h = floor === 0 ? floorH : eaves - floorH;

    // Street face (+X). Ground: front door plus a window. First floor: the two
    // windows that make this map — everything below is watched from here.
    const front = floor === 0
      ? [{ u: -1.2, w: 1.3, y: 0, h: doorH }, { u: 3.2, w: 1.8, y: winY, h: winH }]
      : [{ u: -3.4, w: 1.6, y: 0.9, h: winH }, { u: 1.4, w: 1.8, y: 0.9, h: winH }, { u: 5.0, w: 1.4, y: 0.9, h: winH }];
    wallWithHoles(A, pm, key, hw, 0, -H, spec.d, y0, h, t, front, masks);
    decorateOpenings(A, rng, pm, hw, 0, -H, y0, front, t, floor);

    // Back face (-X): the alley door, and one upstairs window watching the alley.
    const back = floor === 0
      ? [{ u: 2.0, w: 1.3, y: 0, h: doorH }, { u: -3.6, w: 1.6, y: winY, h: winH }]
      : [{ u: 0.4, w: 1.6, y: 0.9, h: winH }];
    wallWithHoles(A, pm, key, -hw, 0, H, spec.d, y0, h, t, back, masks);
    decorateOpenings(A, rng, pm, -hw, 0, H, y0, back, t, floor);

    // The two end faces, one window each, aimed up and down the alleys.
    for (const sz of [-1, 1]) {
      const holes = [{ u: sz * 1.6, w: 1.6, y: floor === 0 ? winY : 0.9, h: winH }];
      const wallRy = sz > 0 ? 0 : Math.PI;
      wallWithHoles(A, pm, key, 0, sz * hd, wallRy, spec.w, y0, h, t, holes, masks);
      decorateOpenings(A, rng, pm, 0, sz * hd, wallRy, y0, holes, t, floor);
    }
  }

  // ---- refinery facade bands ---------------------------------------------
  // Dark brick plinth + red safety stripe are the two strongest value/chroma
  // cues in the LOW reference. They merge into one batch per material across
  // both buildings.
  for (const sx of [-1, 1]) {
    A.add('gb_brick', BOX_THIN(A), LL(pm, sx * (hw + 0.01), 0.42, 0, -H, spec.d - 0.12, 0.84, 0.08), {
      masks: [0.56, 0.52, 0.42],
    });
    A.add('gb_red', BOX_THIN(A), LL(pm, sx * (hw + 0.02), eaves - 0.56, 0, -H, spec.d + 0.04, 0.24, 0.075), {
      masks: [0.72, 0.28, 0.20],
    });
  }
  for (const sz of [-1, 1]) {
    A.add('gb_brick', BOX_THIN(A), LL(pm, 0, 0.42, sz * (hd + 0.01), 0, spec.w - 0.12, 0.84, 0.08), {
      masks: [0.56, 0.52, 0.42],
    });
    A.add('gb_red', BOX_THIN(A), LL(pm, 0, eaves - 0.56, sz * (hd + 0.02), 0, spec.w + 0.04, 0.24, 0.075), {
      masks: [0.72, 0.28, 0.20],
    });
  }

  // ---- industrial facade panel breakup ----------------------------------
  // Large blank wall fields are what made the old map read as a blockout.
  // These shallow seams / service rails create the same large-panel rhythm as
  // the reference refinery while staying in existing gb_dark / gb_grey batches.
  for (const sx of [-1, 1]) {
    for (let z = -hd + 1.65; z <= hd - 1.65; z += 2.35) {
      A.add(
        'gb_dark',
        BOX_THIN(A),
        LL(pm, sx * (hw + 0.025), eaves * 0.51, z, -H, 0.035, eaves - 1.2, 0.045),
        null
      );
    }
  }
  for (const sz of [-1, 1]) {
    for (let x = -hw + 1.5; x <= hw - 1.5; x += 2.25) {
      A.add(
        'gb_dark',
        BOX_THIN(A),
        LL(pm, x, eaves * 0.51, sz * (hd + 0.025), 0, 0.035, eaves - 1.2, 0.045),
        null
      );
    }
  }

  // A mid-height service band plus two compact wall cabinets on the street
  // face. These add industrial scale/readability without new materials.
  A.add(
    'gb_grey',
    BOX_THIN(A),
    LL(pm, hw + 0.035, 2.62, 0, -H, spec.d - 0.9, 0.10, 0.055),
    { masks: [0.58, 0.36, 0.22] }
  );
  for (const z of [-3.9, 3.6]) {
    A.add(
      'gb_grey',
      BOX(A),
      LL(pm, hw + 0.18, 1.48, z, 0, 0.28, 0.78, 0.62),
      { masks: [0.62, 0.32, 0.20] }
    );
    A.add(
      'gb_red',
      BOX_THIN(A),
      LL(pm, hw + 0.335, 1.66, z, -H, 0.035, 0.24, 0.24),
      null
    );
  }

  // ---- the stair ---------------------------------------------------------
  // Publishes its foot in the returned info so the self-test can assert the run
  // -up is clear: a stair blocked by dressing is the one mistake that makes a
  // house's upper floor unreachable, and no screenshot shows it.
  const stairX = -hw + 1.3;
  const stairZ = -hd + 0.6;
  stairRun(A, pm, stairX, 0, stairZ, 1.9, 16, floorH / 16, 0.27, { key: 'gb_grid', railing: 'right' });

  // ---- flat refinery roof ------------------------------------------------
  // The old pitched suburban roof was the single strongest "not a refinery"
  // silhouette in the map. The LOW target uses a flat service roof, parapet,
  // yellow safety rails and a compact HVAC/duct cluster.
  A.add('gb_dark', BOX(A), LL(pm, 0, eaves + 0.10, 0, 0, spec.w + 0.55, 0.22, spec.d + 0.55), {
    masks: [0.58, 0.42, 0.26],
  });

  // Parapet kerbs.
  for (const sx of [-1, 1])
    A.add('gb_grey', BOX_THIN(A), LL(pm, sx * (hw + 0.22), eaves + 0.37, 0, -H, spec.d + 0.35, 0.42, 0.16), null);
  for (const sz of [-1, 1])
    A.add('gb_grey', BOX_THIN(A), LL(pm, 0, eaves + 0.37, sz * (hd + 0.22), 0, spec.w + 0.35, 0.42, 0.16), null);

  // Yellow safety railing on the street edge + one return. Sparse enough to be
  // cheap, dense enough to give the skyline the same industrial rhythm as the
  // reference screenshots.
  const railY = eaves + 0.86;
  A.add('gb_accent', BOX_THIN(A), LL(pm, hw + 0.31, railY, 0, -H, spec.d - 1.0, 0.06, 0.06), null);
  A.add('gb_accent', BOX_THIN(A), LL(pm, hw + 0.31, railY - 0.34, 0, -H, spec.d - 1.0, 0.05, 0.05), null);
  for (let z = -hd + 0.8; z <= hd - 0.8; z += 1.8)
    A.add('gb_accent', BOX_THIN(A), LL(pm, hw + 0.31, railY - 0.18, z, 0, 0.055, 0.74, 0.055), null);

  // Rooftop HVAC: a box, a darker fan face and two service pipes.
  A.add('gb_grey', BOX(A), LL(pm, -1.5, eaves + 0.72, 1.35, 0, 1.7, 1.0, 1.25), {
    masks: [0.66, 0.34, 0.22],
  });
  A.add('gb_dark', BOX_THIN(A), LL(pm, -0.62, eaves + 0.72, 1.35, -H, 0.05, 0.72, 0.78), null);
  for (const dz of [-0.22, 0.22])
    A.add('gb_grey', BOX_THIN(A), LL(pm, 0.55, eaves + 0.92, 1.35 + dz, 0, 0.13, 1.15, 0.13), null);

  // Keep a simple collision lid: roof is not player-accessible but projectiles
  // and ray tests should still hit a solid industrial mass.
  A.box('concrete', ...worldOf(pm, 0, eaves + 0.12, 0), spec.w + 0.4, 0.28, spec.d + 0.4, ryOf(pm));

  // ---- porch -------------------------------------------------------------
  // A flat canopy on two posts over the front door. Overhead only: it is 3 m up
  // and unreachable, so it costs cover nothing and gives the facade a shadow.
  const px = hw + 1.5;
  A.add('gb_white', BOX(A), LL(pm, px, floorH - 0.15, -1.2, 0, 3.4, 0.2, 4.6), { masks: [0.7, 0.35, 0.2] });
  for (const pz of [-3.3, 0.9]) {
    pbox(A, pm, 'gb_white', hw + 2.9, floorH / 2, pz, 0, 0.22, floorH, 0.22, [0.75, 0.3, 0.15]);
  }
  // Two steps up to the threshold.
  for (let i = 0; i < 2; i++)
    pbox(A, pm, 'gb_grid', hw + 0.6 + i * 0.42, 0.09 + i * 0.09, -1.2, 0, 0.5, 0.18, 2.2, [0.6, 0.5, 0.3]);

  // Real construction cues: base course, eave/fascia lines and downpipes.
  // All share existing static material batches, so they do not add draw calls.
  for (const sx of [-1, 1]) {
    A.add('gb_grey', BOX_THIN(A), LL(pm, sx * hw, 0.23, 0, -H, spec.d - 0.35, 0.18, 0.08), {
      masks: [0.45, 0.65, 0.4],
    });
    A.add('gb_grey', BOX_THIN(A), LL(pm, sx * (hw + 0.04), eaves - 0.06, 0, -H, spec.d + 0.2, 0.12, 0.10), {
      masks: [0.72, 0.3, 0.18],
    });
  }
  for (const sz of [-1, 1]) {
    A.add('gb_grey', BOX_THIN(A), LL(pm, 0, 0.23, sz * hd, 0, spec.w - 0.35, 0.18, 0.08), {
      masks: [0.45, 0.65, 0.4],
    });
    A.add('gb_grey', BOX_THIN(A), LL(pm, 0, eaves - 0.06, sz * (hd + 0.04), 0, spec.w + 0.2, 0.12, 0.10), {
      masks: [0.72, 0.3, 0.18],
    });
  }
  for (const z of [-hd + 0.4, hd - 0.4])
    A.add('gb_grey', BOX_THIN(A), LL(pm, hw + 0.09, eaves / 2, z, 0, 0.10, eaves - 0.3, 0.10), {
      masks: [0.6, 0.5, 0.3],
    });

  // Copied, not aliased: `worldOf` returns a shared scratch array, so both
  // houses would otherwise hand back the same one and report the same stair.
  return { spec, id: spec.id, stair: [...worldOf(pm, stairX, 0, stairZ - 1.6)] };
}

/** The sign gantry: two poles, a board, and the map's only reason to look up. */
function buildSign(A, rng) {
  const { poleX, poleH, boardY, boardH, boardT } = SIGN;
  for (const sx of [-1, 1]) {
    A.add('gb_grey', BOX(A), LL(IDENT, sx * poleX, poleH / 2, SIGN.z, 0, 0.3, poleH, 0.3), {
      masks: [0.8, 0.45, 0.2],
    });
    A.box('metal', sx * poleX, poleH / 2, SIGN.z, 0.34, poleH, 0.34);
    // A foot, so the pole meets the road instead of ending in it.
    A.add('gb_grid', BOX(A), LL(IDENT, sx * poleX, 0.16, SIGN.z, 0, 0.8, 0.32, 0.8), { masks: [0.6, 0.5, 0.3] });
  }
  const span = poleX * 2;
  A.add('gb_red', BOX(A), LL(IDENT, 0, boardY + boardH / 2, SIGN.z, 0, span, boardH, boardT), {
    masks: [0.7, 0.4, 0.2],
  });
  A.box('metal', 0, boardY + boardH / 2, SIGN.z, span, boardH, boardT);
  // A band top and bottom: two boxes are the cheapest thing that reads as
  // lettering from 20 m, and lettering is what makes it a sign and not a wall.
  for (const sy of [-1, 1])
    A.add('gb_white', BOX_THIN(A),
      LL(IDENT, 0, boardY + boardH / 2 + sy * (boardH / 2 - 0.16), SIGN.z, 0, span * 0.9, 0.16, boardT + 0.06),
      { masks: [0.9, 0.2, 0.1] });
  // The cross-brace under the board, so the span does not read as floating.
  A.add('gb_grey', BOX_THIN(A), LL(IDENT, 0, boardY - 0.12, SIGN.z, 0, span, 0.14, 0.14), {
    masks: [0.8, 0.5, 0.2],
  });
}

/** Everything that is a low wall: yard walls and street barricades. */
function buildWalls(A, rng) {
  for (const [x, z, ry, len] of YARD_WALLS) lowWall(A, 'gb_grid', x, z, ry, len, 1.2, 0.35);
  for (const [x, z, ry, len] of STREET_BLOCKS) lowWall(A, 'gb_grid', x, z, ry, len, 1.1, 0.8, [0.65, 0.55, 0.35]);
}

/**
 * The four yard sheds. A box, a shallow mono-pitch roof and a door panel — the
 * silhouette is doing all the work here, so the geometry stops at three parts.
 */
function buildSheds(A, rng) {
  for (const [x, z, w, d, h] of SHEDS) {
    A.add('gb_white', BOX(A), LL(IDENT, x, h / 2, z, 0, w, h, d), { masks: [0.5, 0.5, 0.35] });
    A.box('concrete', x, h / 2, z, w, h, d);
    // The roof oversails the box by 15 cm and leans 6°, so the shed reads as
    // built rather than extruded, for one extra part.
    A.add('gb_dark', BOX(A), LL(IDENT, x, h + 0.14, z, 0, w + 0.3, 0.18, d + 0.3, 0, 0.1), {
      masks: [0.65, 0.45, 0.25],
    });
    A.add('gb_red', BOX_THIN(A), LL(IDENT, x, h - 0.42, z + d / 2 + 0.03, 0, w - 0.3, 0.16, 0.05), null);
    // A door on the face that looks back at the street.
    A.add('gb_dark', BOX_THIN(A),
      LL(IDENT, x - Math.sign(x) * (w / 2 + 0.02), 1.05, z, 0, 0.06, 2.1, 1.0), { masks: [0.6, 0.5, 0.4] });
  }
}

/**
 * Set dressing. Instanced props only, and nothing the brief excludes: no
 * foliage, no vehicles. Every placement is filtered through `free()` so a crate
 * never lands inside a wall the occupancy tests believe is empty.
 */
function buildRefinerySkyline(A) {
  if (A.quality === 'performance') return;

  const online = A.onlineAssets ?? {};
  const stack =
    online.chimney ??
    A.cache('nuke:ref-stack', () => {
      const g = new THREE.CylinderGeometry(0.48, 0.58, 1, 10, 1, false);
      g.computeVertexNormals();
      return g;
    });
  const tank =
    online.tank ??
    A.cache('nuke:ref-tank', () => {
      const g = new THREE.CylinderGeometry(1.55, 1.55, 1, 12, 1, false);
      g.computeVertexNormals();
      return g;
    });
  const pipe = A.cache('nuke:ref-pipe', () => {
    const g = new THREE.CylinderGeometry(0.11, 0.11, 1, 8, 1, false);
    g.computeVertexNormals();
    return g;
  });

  // Chimney stacks beyond the playable wall.
  for (const [x, z, h] of [
    [-31, -25, 11.5], [-27.8, -24.2, 8.8],
    [31.5, 24.0, 12.5], [28.3, 23.5, 9.4],
  ]) {
    A.add('gb_white', stack, LL(IDENT, x, h / 2, z, 0, 1, h, 1), null);
    for (const f of [0.72, 0.88])
      A.add('gb_red', stack, LL(IDENT, x, h * f, z, 0, 1.06, 0.72, 1.06), null);
  }

  // Two storage tanks with red crown bands.
  for (const [x, z, h] of [[-32.5, 6.5, 5.2], [32.0, -5.5, 6.0]]) {
    A.add('gb_white', tank, LL(IDENT, x, h / 2, z, 0, 1, h, 1), null);
    A.add('gb_red', tank, LL(IDENT, x, h - 0.42, z, 0, 1.03, 0.36, 1.03), null);
  }

  // Real CC0 industrial shells beyond the playable wall. They are scenery only,
  // so no collision is generated and the competitive layout remains identical.
  if (online.building) {
    A.add('gb_white', online.building, LL(IDENT, -33.5, 0, -12.0, 0.20, 8.8, 8.8, 8.8), null);
  }
  if (online.buildingAlt) {
    A.add('gb_grey', online.buildingAlt, LL(IDENT, 27.0, 0, -18.5, Math.PI + 0.06, 7.4, 7.4, 7.4), null);
  }
  if (online.chimneyLarge) {
    A.add('gb_white', online.chimneyLarge, LL(IDENT, 23.8, 0, 28.5, 0, 11.0, 11.0, 11.0), null);
    A.add('gb_red', online.chimneyLarge, LL(IDENT, 23.8, 8.6, 28.5, 0, 11.2, 1.2, 11.2), null);
  }

  // Higher-detail CC0 hero building. It sits beyond the playable wall and uses
  // Hideverse's own light concrete, so it adds authored industrial silhouette
  // without changing collision or material cost.
  if (online.treyLoadingBay) {
    A.add(
      'gb_white',
      online.treyLoadingBay,
      LL(IDENT, -27.5, 0.02, -17.8, 0.08, 10.5, 10.5, 10.5),
      null
    );
    A.add(
      'gb_white',
      online.treyLoadingBay,
      LL(IDENT, 27.2, 0.02, 17.5, Math.PI + 0.06, 9.8, 9.8, 9.8),
      null
    );
  }

  if (online.treyElevatedWalkway) {
    A.add(
      'gb_accent',
      online.treyElevatedWalkway,
      LL(IDENT, 0, 2.15, 23.8, 0, 11.5, 11.5, 11.5),
      null
    );
  }

  // Yellow pipe rack / catwalk silhouette across the far skyline.
  for (const side of [-1, 1]) {
    const z = side * 27.0;
    for (const x of [-18, -9, 0, 9, 18])
      A.add('gb_dark', BOX_THIN(A), LL(IDENT, x, 4.5, z, 0, 0.12, 7.0, 0.12), null);
    for (const y of [4.0, 5.4, 6.7])
      A.add('gb_accent', BOX_THIN(A), LL(IDENT, 0, y, z, 0, 38, 0.08, 0.08), null);
    for (const x of [-12, 12])
      A.add('gb_grey', pipe, LL(IDENT, x, 5.0, z - side * 0.45, 0, 1, 8.0, 1, 0, Math.PI / 2), null);
  }
}

function addIndustrialArtifacts(A) {
  if (A.quality === 'performance') return;

  const online = A.onlineAssets ?? {};
  const box = BOX(A);
  const thin = BOX_THIN(A);
  const wheel = A.cache('nuke:artifact-wheel', () => {
    const g = new THREE.CylinderGeometry(0.34, 0.34, 0.18, 8, 1, false);
    g.rotateZ(Math.PI / 2);
    g.computeVertexNormals();
    return g;
  });
  const pipe = A.cache('nuke:artifact-pipe', () => {
    const g = new THREE.CylinderGeometry(0.075, 0.075, 1, 8, 1, false);
    g.computeVertexNormals();
    return g;
  });
  const drum = A.cache('nuke:artifact-drum', () => {
    const g = new THREE.CylinderGeometry(0.28, 0.28, 0.82, 12, 1, false);
    g.computeVertexNormals();
    return g;
  });
  const cone =
    online.cone ??
    A.cache('nuke:artifact-cone', () => {
      const g = new THREE.ConeGeometry(0.24, 0.62, 8, 1, false);
      g.computeVertexNormals();
      return g;
    });

  // ------------------------------------------------------ forklift / loader
  // One strong hero prop like the reference screenshots. Every piece uses an
  // existing map batch, so this changes geometry density without adding shader
  // or material families.
  const fx = -13.4, fz = 5.9, fry = Math.PI * 0.5;
  const fm = LL(IDENT, fx, 0, fz, fry);

  // chassis + counterweight
  A.add('gb_accent', box, LL(fm, 0, 0.50, 0.10, 0, 1.35, 0.62, 1.75), {
    masks: [0.7, 0.42, 0.22],
  });
  A.add('gb_accent', box, LL(fm, 0, 0.82, 0.62, 0, 1.18, 0.36, 0.68), {
    masks: [0.72, 0.36, 0.20],
  });
  // cabin / seat / roof
  A.add('gb_dark', box, LL(fm, 0, 1.12, -0.12, 0, 0.78, 0.38, 0.66), null);
  A.add('gb_dark', thin, LL(fm, 0, 1.77, 0.02, 0, 1.28, 0.10, 1.22), null);
  for (const sx of [-1, 1])
    for (const sz of [-1, 1])
      A.add('gb_dark', thin, LL(fm, sx * 0.52, 1.32, sz * 0.45, 0, 0.07, 0.95, 0.07), null);

  // mast + forks
  for (const sx of [-1, 1])
    A.add('gb_dark', thin, LL(fm, sx * 0.42, 1.10, -1.05, 0, 0.10, 1.85, 0.10), null);
  for (const sx of [-1, 1])
    A.add('gb_grey', thin, LL(fm, sx * 0.34, 0.18, -1.72, 0, 0.10, 0.08, 1.55), null);
  A.add('gb_dark', thin, LL(fm, 0, 0.72, -1.06, 0, 0.92, 0.12, 0.10), null);

  // four wheels
  for (const sx of [-1, 1])
    for (const sz of [-1, 1])
      A.add('gb_dark', wheel, LL(fm, sx * 0.70, 0.34, sz * 0.63, 0, 1, 1, 1), null);

  // coarse cover proxy for player collision
  A.box('metal', fx, 0.80, fz, 2.0, 1.60, 2.55, fry);

  // -------------------------------------------------------- safety cones
  for (const [x, z, ry] of [
    [-10.8, 7.0, 0.0],
    [-9.6, 6.35, 0.1],
    [10.3, -7.0, -0.08],
    [18.0, 11.7, 0.06],
  ]) {
    const cs = online.cone ? 0.68 : 1;
    A.add('gb_accent', cone, LL(IDENT, x, 0.31, z, ry, cs, cs, cs), {
      masks: [0.78, 0.28, 0.16],
    });
    A.add('gb_white', thin, LL(IDENT, x, 0.37, z, ry, 0.31, 0.07, 0.31), null);
    A.add('gb_dark', thin, LL(IDENT, x, 0.025, z, ry, 0.56, 0.05, 0.56), null);
  }

  // ------------------------------------------------------------- drums
  for (const [x, z] of [
    [-17.2, 8.8], [-16.55, 8.95], [17.4, -8.9],
  ]) {
    A.add('gb_dark', drum, LL(IDENT, x, 0.41, z, 0, 1, 1, 1), {
      masks: [0.66, 0.42, 0.28],
    });
    A.add('gb_dark', thin, LL(IDENT, x, 0.22, z, 0, 0.60, 0.035, 0.60), null);
    A.add('gb_dark', thin, LL(IDENT, x, 0.62, z, 0, 0.60, 0.035, 0.60), null);
  }

  // ------------------------------------------------ utility-wall details
  // External pipes, service boxes and louvred vent panels: these are the cheap
  // industrial cues that make a low-graphics wall read as "built", not as a
  // blank block.
  for (const sx of [-1, 1]) {
    const x = sx * 17.05;
    const z0 = sx > 0 ? 5.0 : -5.0;

    // two vertical service pipes + horizontal header
    for (let i = 0; i < 2; i++) {
      A.add('gb_grey', pipe, LL(IDENT, x, 1.55, z0 + i * 0.34, 0, 1, 2.6, 1), {
        masks: [0.72, 0.34, 0.18],
      });
    }
    A.add('gb_grey', pipe, LL(IDENT, x, 2.72, z0 + 0.17, 0, 1, 0.80, 1, 0, Math.PI / 2), null);

    // electrical service cabinet + small warning plate
    A.add('gb_grey', box, LL(IDENT, x - sx * 0.04, 1.05, z0 + 1.05, 0, 0.26, 0.72, 0.62), {
      masks: [0.62, 0.28, 0.16],
    });
    A.add('gb_accent', thin, LL(IDENT, x - sx * 0.19, 1.23, z0 + 1.05, 0, 0.03, 0.22, 0.25), null);

    // louvred vent panel: outer frame + four dark blades
    A.add('gb_grey', thin, LL(IDENT, x - sx * 0.16, 1.92, z0 - 0.95, 0, 0.04, 0.92, 1.12), {
      masks: [0.7, 0.32, 0.2],
    });
    for (let i = 0; i < 4; i++)
      A.add('gb_dark', thin, LL(IDENT, x - sx * 0.20, 1.62 + i * 0.20, z0 - 0.95, 0, 0.03, 0.08, 0.90), null);
  }

  // ------------------------------------------------ real CC0 factory geometry
  // These replace the weakest procedural silhouettes with actual Kenney factory
  // meshes. They still render through our existing LOW material keys.
  if (online.machine) {
    for (const [x, z, ry, sc, key] of [
      [-15.8, -10.8, 0.18, 2.0, 'gb_grey'],
      [15.4, 10.6, Math.PI - 0.20, 1.85, 'gb_accent'],
    ]) {
      A.add(key, online.machine, LL(IDENT, x, 0.02, z, ry, sc, sc, sc), null);
    }
  }

  if (online.catwalk) {
    for (const [x, z, ry] of [
      [-14.8, 11.2, 0],
      [14.8, -11.2, Math.PI],
    ]) {
      A.add('gb_accent', online.catwalk, LL(IDENT, x, 2.55, z, ry, 4.2, 4.2, 4.2), null);
    }
  }

  if (online.pipeValve) {
    for (const [x, z, ry] of [
      [-16.95, 1.6, Math.PI / 2],
      [16.95, -1.7, -Math.PI / 2],
    ]) {
      A.add('gb_grey', online.pipeValve, LL(IDENT, x, 1.35, z, ry, 1.35, 1.35, 1.35), null);
    }
  }

  if (online.factoryDoor) {
    for (const [x, z, ry] of [
      [-16.82, -5.6, Math.PI / 2],
      [16.82, 5.8, -Math.PI / 2],
    ]) {
      A.add('gb_dark', online.factoryDoor, LL(IDENT, x, 0.02, z, ry, 2.35, 2.35, 2.35), null);
    }
  }

  if (online.machineWindow) {
    A.add('gb_grey', online.machineWindow, LL(IDENT, -13.8, 0.02, 12.4, 0.1, 2.15, 2.15, 2.15), null);
  }

  if (online.catwalkStairs) {
    A.add('gb_accent', online.catwalkStairs, LL(IDENT, 18.1, 0.02, -9.6, Math.PI, 3.7, 3.7, 3.7), null);
  }

  if (online.pipeLong) {
    for (const [x, y, z, ry, sc] of [
      [-15.7, 3.55, -2.2, 0, 4.2],
      [15.7, 3.85, 2.0, Math.PI, 4.0],
      [0.0, 5.10, 17.6, Math.PI / 2, 5.2],
    ]) {
      A.add('gb_grey', online.pipeLong, LL(IDENT, x, y, z, ry, sc, sc, sc), null);
    }
  }

  if (online.pipeBend) {
    for (const [x, y, z, ry, sc] of [
      [-15.7, 3.55, 1.2, 0, 2.2],
      [15.7, 3.85, -1.0, Math.PI, 2.2],
    ]) {
      A.add('gb_grey', online.pipeBend, LL(IDENT, x, y, z, ry, sc, sc, sc), null);
    }
  }

  if (online.conveyor) {
    A.add('gb_dark', online.conveyor, LL(IDENT, 9.4, 1.10, -14.3, Math.PI, 3.6, 3.6, 3.6), null);
  }

  // Second-wave geometry: each model is unique and used sparingly so LOW gains
  // authored industrial silhouette without duplicating large meshes.
  if (online.machineFortified) {
    A.add('gb_grey', online.machineFortified, LL(IDENT, -10.6, 0.02, -14.6, 0.12, 2.7, 2.7, 2.7), null);
  }
  if (online.catwalkCorner) {
    A.add('gb_accent', online.catwalkCorner, LL(IDENT, -8.8, 2.6, 13.3, Math.PI / 2, 3.9, 3.9, 3.9), null);
  }
  if (online.pipeCross) {
    A.add('gb_grey', online.pipeCross, LL(IDENT, 15.7, 1.55, 2.7, -Math.PI / 2, 1.55, 1.55, 1.55), null);
  }
  if (online.pipeJunction) {
    A.add('gb_grey', online.pipeJunction, LL(IDENT, -15.8, 1.42, -2.8, Math.PI / 2, 1.45, 1.45, 1.45), null);
  }
  if (online.wideDoor) {
    A.add('gb_dark', online.wideDoor, LL(IDENT, -16.80, 0.02, 5.8, Math.PI / 2, 2.65, 2.65, 2.65), null);
  }
  if (online.conveyorFence) {
    A.add('gb_accent', online.conveyorFence, LL(IDENT, -9.3, 1.05, 14.4, 0, 3.1, 3.1, 3.1), null);
  }

  // ------------------------------------------------ overhead pipe gantry
  // A clean refinery silhouette across the street, safely above player height.
  // Two uprights sit outside the drivable lane, and three coloured process
  // pipes bridge the road. This is one of the strongest cues in the reference.
  const gz = -10.2;
  for (const sx of [-1, 1]) {
    const gx = sx * 6.75;
    A.add('gb_dark', box, LL(IDENT, gx, 2.30, gz, 0, 0.20, 4.60, 0.20), null);
    A.add('gb_accent', thin, LL(IDENT, gx, 4.55, gz, 0, 0.78, 0.08, 0.36), null);
  }
  for (const [y, key] of [[4.10, 'gb_grey'], [4.42, 'gb_red'], [4.74, 'gb_grey']]) {
    A.add(key, pipe, LL(IDENT, 0, y, gz, 0, 1, 13.4, 1, 0, Math.PI / 2), null);
  }

  // ------------------------------------------------ loading/service bay
  // Pallet stack, dark drums and a safety rail grouped as one believable work
  // zone rather than randomly scattered clutter.
  const bayX = 12.8;
  const bayZ = -12.4;
  for (let i = 0; i < 3; i++) {
    A.add(
      'wood_prop',
      thin,
      LL(IDENT, bayX + i * 0.34, 0.13 + i * 0.16, bayZ + i * 0.08, -0.05, 1.55, 0.12, 0.82),
      null
    );
  }
  for (const dz of [-0.72, -0.08, 0.56]) {
    A.add('gb_dark', drum, LL(IDENT, bayX + 1.45, 0.41, bayZ + dz, 0, 1, 1, 1), null);
  }
  for (const x of [bayX - 1.25, bayX + 2.35]) {
    A.add('gb_accent', thin, LL(IDENT, x, 0.72, bayZ + 1.10, 0, 0.07, 1.22, 0.07), null);
  }
  A.add('gb_accent', thin, LL(IDENT, bayX + 0.55, 1.26, bayZ + 1.10, 0, 3.65, 0.07, 0.07), null);
  A.add('gb_accent', thin, LL(IDENT, bayX + 0.55, 0.78, bayZ + 1.10, 0, 3.65, 0.055, 0.055), null);
}

function dress(A, rng, stairFeet) {
  const free = (x, z, m = 0.5) => {
    if (!isOpenNuketown(x, z, m)) return false;
    // Keep the stair run-ups clear — see the note in `buildHouse`.
    for (const f of stairFeet) if (Math.hypot(x - f[0], z - f[2]) < 2.6) return false;
    return true;
  };

  /**
   * Real placement, still deterministic. Loose crates/drums get a few degrees
   * of yaw/tilt and a small scale spread; fixed barriers and vehicles stay
   * plumb. The prototypes remain instanced, so variation costs no extra draws.
   */
  A.jitter = { rng, yaw: 0.12, scale: 0.045 };
  // `Rng.int` takes (min, max). Called with one argument it returns NaN, which
  // does not throw and does not fail any headless check — it propagates into
  // the instance matrix, then into the InstancedMesh's bounding sphere, and
  // three culls the whole cloud every frame. 82 of this map's 122 props were
  // invisible exactly that way, and only a scaled-up prop that STILL did not
  // appear on screen gave it away.
  const turn = () => Math.floor(rng.float() * 4) * H;

  // Industrial low-graphics dressing inspired by the target reference: forklift,
  // cones, drums, service pipes, vent panels and electrical boxes. All merge
  // into existing material batches.
  addIndustrialArtifacts(A);

  /** One merged timber crate: body, posts, slats and lid in one draw. */
  const crate = (x, y, z, ry) => {
    A.put('gb_crate', x, y, z, ry, 1, [1, rng.range(0.85, 1.2), 1]);
  };

  // ---- poured road barriers: sidewalk line and alley cover --------------
  const blocks = [
    [-7.9, -12.0, 0], [-7.9, -3.0, 0], [-7.9, 6.0, 0], [-7.9, 14.0, 0],
    [7.9, 12.0, 0], [7.9, 3.0, 0], [7.9, -6.0, 0], [7.9, -14.0, 0],
    [-4.2, -17.6, H], [4.2, -17.6, H], [-4.2, 17.6, H], [4.2, 17.6, H],
    [-20.0, -18.4, H], [20.0, 18.4, H], [-23.6, 13.5, 0], [23.6, -13.5, 0],
    [-19.0, -15.5, 0], [19.0, 15.5, 0], [-24.0, 11.0, H], [24.0, -11.0, H],
    [-6.0, 19.0, 0], [6.0, -19.0, 0],
  ];
  for (const [x, z, ry] of blocks) if (free(x, z, 0.9)) A.put('gb_block', x, 0.46, z, ry, 1);

  // The LOW refinery pass intentionally omits suburban parked cars. The
  // forklift, barriers, crates and service equipment carry cover/readability.
  // ---- crates, on the ground and stacked ---------------------------------
  const crates = [
    [-23.5, -13.0], [-24.2, 7.0],
    [23.5, 13.0], [24.2, -7.0],
    [-10.2, -13.5], [-16.5, -13.0], [-20.5, -12.5],
    [10.2, 13.5], [16.5, 13.0], [20.5, 12.5],
    [-12.0, 10.5], [12.0, -10.5],
  ];
  const S = 0.92;
  for (let i = 0; i < crates.length; i++) {
    const [x, z] = crates[i];
    if (!free(x, z, 0.6)) continue;
    crate(x, S / 2 + 0.02, z, turn());
    // Every third one carries a second tier. A stack is what gives a blockout
    // its only vertical rhythm, and it is free: the same prototype again.
    if (i % 4 === 0) crate(x, S * 1.5 + 0.03, z, turn());
  }

  // Oil-drum clutter was removed from the competitive layout. Cars, barriers
  // and timber crates already provide the silhouette rhythm; another repeated
  // instanced prototype cost a draw/program for little spatial value.

  /**
   * Crate piles: a 3-2-1 pyramid in each yard and each far lot.
   *
   * The reference blockouts all have one — it is the shape that tells you a
   * blockout is a place rather than a diagram, and it is the only object here
   * taller than a crate that is not a building. Kept 2 m clear of every spawn
   * point: `buildSpawnPoints` culls a spawn against real collision, so a pile
   * dropped on one does not fail anything, it just quietly ships a point short.
   */
  for (const [cx, cz] of [[-10.3, -2.5], [10.3, 2.5]]) {
    const ry = turn();
    const cos = Math.cos(ry);
    const sin = Math.sin(ry);
    for (let row = 0; row < 2; row++) {
      const n = 2 - row;
      for (let i = 0; i < n; i++) {
        const u = (i - (n - 1) / 2) * (S + 0.03);
        const x = cx + cos * u;
        const z = cz - sin * u;
        if (!free(x, z, 0.55)) continue;
        crate(x, S / 2 + 0.02 + row * S, z, ry);
      }
    }
  }

  // Small grounded debris replaces some of the removed prop repetition. These
  // pieces merge into existing wood/concrete batches, so they cost no new draw.
  for (const [x, z, ry, key] of [
    [-8.8, -15.2, 0.22, 'gb_dark'],
    [-18.4, 9.8, -0.34, 'gb_dark'],
    [8.6, 15.0, -0.18, 'gb_grey'],
    [18.0, -10.0, 0.31, 'gb_grey'],
    [-3.8, 17.6, 0.10, 'gb_dark'],
    [3.6, -17.8, -0.12, 'gb_grey'],
  ]) {
    if (!free(x, z, 0.25)) continue;
    A.add(key, BOX_THIN(A), LL(IDENT, x, 0.055, z, ry, 0.72, 0.09, 0.18), {
      masks: [0.82, 0.62, 0.38],
    });
  }

  // Vegetation is intentionally omitted from the competitive path: alpha-cut
  // foliage costs an extra shader/program/texture family. The built environment
  // now carries the realism budget instead.
  A.jitter = null;
}

/**
 * Build the level. Called by `WorldSystem` with a fresh Assembler and its own
 * RNG fork — same contract as every other map's `build`.
 */
export function buildNuketown(A, rng) {
  registerProps(A, rng);
  registerNuketownProps(A, rng);

  buildGround(A, rng);
  buildPerimeter(A, rng);
  buildWalls(A, rng);
  buildSheds(A, rng);
  buildSign(A, rng);
  buildRefinerySkyline(A);

  const infos = [];
  for (const h of HOUSES) infos.push(buildHouse(A, rng, h));

  dress(A, rng, infos.map((i) => i.stair));

  return { buildings: infos };
}

